83:   const myTmpDir = fs.mkdtempSync(path.join(tmpdir(), 'check_pot-'));
84:   temporaryDirs.push(myTmpDir); // Cleanup will be done on process.exit()
85:   try {
86:     // Extract the strings from the source code
87:     execSync(`npx ttag extract -o ${myTmpDir}/pot ./src/`, { stdio: 'inherit' });
88:     // Generate the `.po` files
89:     execSync(`msgen -o ${myTmpDir}/po ${myTmpDir}/pot`, { stdio: 'inherit' });
90:     // Check if the `.pot` file is outdated
91:     execSync(`msgcmp ${myTmpDir}/po ./locale/texts.pot`, { stdio: 'inherit' });
92:   } catch (error) {
93:     isPotOutdated = true;
94:     console.error('❌ Error checking pot file, or pot file outdated:', error);
95:   }
